"""自动术语提取（issue #31）。

翻译前先通读全文采样，让模型挑出高频专业术语并给出统一译法，再把这张对照表
注入后续每一段的翻译 prompt。这样同一个术语在全文里不会一会儿一个译法。

上游 pdf2zh-next 的内核 BabelDOC 有同类功能（``--no-auto-extract-glossary``
默认开启），但我们的 App 基于 pdf2zh 1.8.9 老内核，没有这条管线，所以自己实现。

特点
----
* **只多花一次模型调用**：全文采样后一次性抽完，不是逐页抽。
* **用户术语库优先**：手工维护的词条永远覆盖自动提取的结果。
* **失败不影响翻译**：抽取出错只是少一张对照表，翻译照常进行。
* **只对大模型服务生效**：Google / Bing / DeepL 这类没有 prompt 概念的服务直接跳过。
"""

from __future__ import annotations

import logging
import re

logger = logging.getLogger(__name__)

MAX_TERMS = 30          # 最多抽多少条。太多会把 prompt 撑大、拖慢每一段
SAMPLE_CHARS = 6000     # 采样多少字符送去抽取
SAMPLE_PAGES = 12       # 最多从多少页里采样
MIN_SRC_LEN = 3         # 太短的词（a / of）没有统一译法的价值
MAX_SRC_LEN = 60

# 分隔符用 ||| 而不是 <TAB>：实测模型会把 "<TAB>" 当字面量写出来，
# 结果译文里多个 T（democratic model → T民主模型）。同时兼容 tab / -> 作退路。
_LINE = re.compile(r"^\s*(?:\d+[.、)]\s*)?(.+?)\s*(?:\|\|\||\t|->)\s*(.+?)\s*$")

_PROMPT = """You are building a terminology table for translating a document from {lang_in} to {lang_out}.

Below is sampled text from the document. Identify the most important domain-specific
technical terms (nouns and noun phrases only) that appear repeatedly and that must be
translated consistently throughout.

Rules:
- At most {max_terms} entries, ordered by importance.
- Only terms whose translation should be fixed. Skip common words.
- Do NOT include headings like "Abstract" or "Introduction".
- Output ONE entry per line, in exactly this format, with no numbering and no extra text:
  <source term> ||| <{lang_out} translation>

Sampled text:
---
{sample}
---"""


def _sample_text(doc) -> str:
    """从文档里均匀采样一段文本。"""
    n = doc.page_count
    if n == 0:
        return ""
    step = max(1, n // SAMPLE_PAGES)
    parts, total = [], 0
    for i in range(0, n, step):
        if total >= SAMPLE_CHARS:
            break
        try:
            t = doc[i].get_text().strip()
        except Exception:
            continue
        if not t:
            continue
        take = t[: max(0, SAMPLE_CHARS - total)]
        parts.append(take)
        total += len(take)
    return "\n\n".join(parts)


def _llm_client(translator):
    """拿到底层的 OpenAI 兼容客户端；不是大模型服务就返回 None。

    注意不能直接用 ``translator.translate()`` —— 它带着「只输出译文」的强约束
    system prompt，把抽取指令丢进去只会被当成待翻译的文本翻一遍。
    """
    client = getattr(translator, "client", None)
    model = getattr(translator, "model", None)
    if client is None or not model:
        return None, None
    # 必须是 openai 风格的 chat.completions 接口
    if not hasattr(client, "chat") or not hasattr(client.chat, "completions"):
        return None, None
    return client, model


def _parse(raw: str) -> dict:
    out = {}
    for line in (raw or "").splitlines():
        line = line.strip()
        if not line or line.startswith(("#", "---", "```")):
            continue
        m = _LINE.match(line)
        if not m:
            continue
        src, dst = m.group(1).strip(), m.group(2).strip()
        src = src.strip("*_`\"' ")
        dst = dst.strip("*_`\"' ")
        if not src or not dst or src.lower() == dst.lower():
            continue
        if not (MIN_SRC_LEN <= len(src) <= MAX_SRC_LEN):
            continue
        if src.lower() in {k.lower() for k in out}:
            continue
        out[src] = dst
        if len(out) >= MAX_TERMS:
            break
    return out


def extract(doc, translator, lang_in: str = "English", lang_out: str = "Chinese",
            status_cb=None) -> dict:
    """从文档里自动抽取术语对照表。失败一律返回空表，绝不抛异常打断翻译。

    :param doc: 已打开的 fitz.Document
    :param translator: pdf2zh 的翻译器实例（用它配置好的 key / 模型）
    """
    try:
        client, model = _llm_client(translator)
        if client is None:
            logger.info("当前翻译服务不是大模型，跳过自动术语提取")
            return {}

        sample = _sample_text(doc)
        if len(sample) < 200:
            logger.info("正文太短（%d 字符），跳过自动术语提取", len(sample))
            return {}

        if status_cb:
            status_cb("正在提取术语…")

        prompt = _PROMPT.format(lang_in=lang_in or "the source language",
                                lang_out=lang_out or "Chinese",
                                max_terms=MAX_TERMS, sample=sample)
        resp = client.chat.completions.create(
            model=model,
            messages=[{"role": "user", "content": prompt}],
            temperature=0,
        )
        raw = (resp.choices[0].message.content or "")
        terms = _parse(raw)
        logger.info("自动提取术语 %d 条", len(terms))
        if status_cb:
            status_cb(f"已提取 {len(terms)} 条术语" if terms else "未提取到术语")
        return terms
    except Exception as e:                      # noqa: BLE001
        logger.warning("自动术语提取失败（不影响翻译）: %s: %s", type(e).__name__, e)
        if status_cb:
            status_cb("术语提取失败，按常规翻译")
        return {}


def merge(auto: dict, manual: dict) -> dict:
    """合并：手工术语库优先，自动提取的只作补充。"""
    merged = dict(auto or {})
    lower = {k.lower(): k for k in merged}
    for k, v in (manual or {}).items():
        dup = lower.get(k.lower())
        if dup is not None and dup != k:
            merged.pop(dup, None)
        merged[k] = v
    return merged
